use std::rc::Rc;

use gpui::{
    div, px, App, ClickEvent, Div, ElementId, InteractiveElement, IntoElement, ParentElement,
    SharedString, Stateful, StatefulInteractiveElement, Styled, Window,
};

use crate::foundation::{Theme, MOTION};
use crate::primitives::Size;

use super::style::chrome;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum ButtonVariant {
    #[default]
    Primary,
    Secondary,
    Ghost,
    Danger,
}

/// Finished KUI button with theme-aware chrome and press feedback.
pub struct Button {
    id: ElementId,
    label: SharedString,
    variant: ButtonVariant,
    size: Size,
    disabled: bool,
    loading: bool,
    on_click: Option<Rc<dyn Fn(&ClickEvent, &mut Window, &mut App)>>,
}

impl Button {
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            label: SharedString::from(""),
            variant: ButtonVariant::Primary,
            size: Size::Md,
            disabled: false,
            loading: false,
            on_click: None,
        }
    }

    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = label.into();
        self
    }

    pub fn primary(mut self) -> Self {
        self.variant = ButtonVariant::Primary;
        self
    }

    pub fn secondary(mut self) -> Self {
        self.variant = ButtonVariant::Secondary;
        self
    }

    pub fn ghost(mut self) -> Self {
        self.variant = ButtonVariant::Ghost;
        self
    }

    pub fn danger(mut self) -> Self {
        self.variant = ButtonVariant::Danger;
        self
    }

    pub fn with_size(mut self, size: Size) -> Self {
        self.size = size;
        self
    }

    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    pub fn loading(mut self, loading: bool) -> Self {
        self.loading = loading;
        self
    }

    pub fn on_click(
        mut self,
        listener: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(listener));
        self
    }

    /// Build with live KUI theme tokens from `App`.
    pub fn into_themed(self, cx: &App) -> Stateful<Div> {
        let theme = Theme::global(cx);
        let look = chrome(self.variant, self.size, &theme.tokens.colors);
        let _press = MOTION.effective(MOTION.snappy, theme.reduced_motion);

        let label = if self.loading {
            SharedString::from("…")
        } else {
            self.label.clone()
        };

        let mut el = div()
            .id(self.id)
            .flex()
            .items_center()
            .justify_center()
            .px(look.pad_x)
            .py(look.pad_y)
            .rounded(look.radius)
            .text_size(look.text)
            .line_height(px(20.))
            .bg(look.bg)
            .text_color(look.fg)
            .child(label);

        if let Some(border) = look.border {
            el = el.border_1().border_color(border);
        }

        if self.disabled || self.loading {
            el = el.opacity(0.5);
        } else if let Some(on_click) = self.on_click.clone() {
            el = el.on_click(move |event, window, cx| on_click(event, window, cx));
        }

        el
    }
}

impl IntoElement for Button {
    type Element = Stateful<Div>;

    fn into_element(self) -> Self::Element {
        // Fallback light chrome when no App borrow is available (static builders).
        let colors = crate::foundation::ColorTokens::light();
        let look = chrome(self.variant, self.size, &colors);
        let label = if self.loading {
            SharedString::from("…")
        } else {
            self.label.clone()
        };

        let mut el = div()
            .id(self.id)
            .flex()
            .items_center()
            .justify_center()
            .px(look.pad_x)
            .py(look.pad_y)
            .rounded(look.radius)
            .text_size(look.text)
            .line_height(px(20.))
            .bg(look.bg)
            .text_color(look.fg)
            .child(label);

        if let Some(border) = look.border {
            el = el.border_1().border_color(border);
        }

        if self.disabled || self.loading {
            el = el.opacity(0.5);
        } else if let Some(on_click) = self.on_click {
            el = el.on_click(move |event, window, cx| on_click(event, window, cx));
        }

        el
    }
}

use gpui::ElementId;

/// Behavior contract for a KUI button-like control (no default chrome).
#[derive(Clone)]
pub struct ButtonBehavior {
    pub id: ElementId,
    pub disabled: bool,
    pub selected: bool,
}

impl ButtonBehavior {
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            disabled: false,
            selected: false,
        }
    }

    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    pub fn selected(mut self, selected: bool) -> Self {
        self.selected = selected;
        self
    }
}

